WHERE {
  ?entity a gleif:LegalEntity ;
          gleif:leiCode ?lei ;
          gleif:incorporatedInCountry <http://countryinfo.org/countries/Germany> ;
          gleif:legalName ?name .
  FILTER(STRSTARTS(?name, "DEUTSCHE BANK"))
}

